
import mongoose, { Schema, type Document, type Types } from "mongoose";

/** Individual learning‑task stored inside a candidate’s learning‑progress document. */
export interface ILearningTask {
  /** Unique identifier generated by Mongoose (ObjectId as string). */
  _id: Types.ObjectId;
  /** Short title, e.g. "Read React Hooks docs". */
  title: string;
  /** Optional longer description. */
  description?: string;
  /** Priority – helps UI sort/colour‑code tasks. */
  priority: "low" | "medium" | "high";
  /** Current status. */
  status: "pending" | "completed";
  /** Estimated duration in minutes (optional). */
  estimatedDuration?: number;
  /** Progress 0‑100% – useful for long activities. */
  progress: number;
  /** Timestamp when the task was marked completed. */
  completedAt?: Date;
}

/** Main learning‑progress document – one per candidate. */
export interface ILearningProgress extends Document {
  userId: Types.ObjectId;
  /** Array of learning tasks. */
  tasks: ILearningTask[];
  /** Convenience array for quick look‑up of completed topic IDs (legacy). */
  completedTopics: string[];
  createdAt: Date;
  updatedAt: Date;
}

/* ---------- Schema Definitions ---------- */

const learningTaskSchema = new Schema<ILearningTask>(
  {
    title: { type: String, required: true, trim: true, minlength: 2, maxlength: 120 },
    description: { type: String, trim: true, maxlength: 1000 },
    priority: { type: String, enum: ["low", "medium", "high"], default: "medium" },
    status: { type: String, enum: ["pending", "completed"], default: "pending" },
    estimatedDuration: { type: Number, min: 1 },
    progress: { type: Number, min: 0, max: 100, default: 0 },
    completedAt: { type: Date },
  },
  { _id: true, timestamps: true }
);

const learningProgressSchema = new Schema<ILearningProgress>(
  {
    userId: { type: Schema.Types.ObjectId, ref: "User", required: true, unique: true, index: true },
    tasks: { type: [learningTaskSchema], default: [] },
    completedTopics: {
      type: [String],
      default: [],
      validate: {
        validator: (topics: string[]) =>
          topics.length <= 100 && topics.every(t => typeof t === "string" && t.length > 0 && t.length <= 200),
        message: "Completed topics must contain at most 100 valid topic IDs.",
      },
    },
  },
  { timestamps: true }
);

export const LearningProgress = mongoose.model<ILearningProgress>("LearningProgress", learningProgressSchema);
